IF FirstScan THEN
    V_3_Out      := 6554;
    V_4_Out      := 6554;
    V_5_Out      := 6554;
    V_7_Out      := 6554;
    FC4_Integral := 0.0;
    FC5_Integral := 0.0;
    FC6_Integral := 0.0;
    TC1_Integral := 0.0;
    FI_1_HH_Latch(S1 := FALSE, R := TRUE);
    FI_1_LL_Latch(S1 := FALSE, R := TRUE);
    FI_2_HH_Latch(S1 := FALSE, R := TRUE);
    FI_2_LL_Latch(S1 := FALSE, R := TRUE);
    FI_3_HH_Latch(S1 := FALSE, R := TRUE);
    FI_3_LL_Latch(S1 := FALSE, R := TRUE);
    TI_1_HH_Latch(S1 := FALSE, R := TRUE);
    TI_1_LL_Latch(S1 := FALSE, R := TRUE);
    TI_4_HH_Latch(S1 := FALSE, R := TRUE);
    TI_4_LL_Latch(S1 := FALSE, R := TRUE);
    TI_5_HH_Latch(S1 := FALSE, R := TRUE);
    TI_5_LL_Latch(S1 := FALSE, R := TRUE);
    TI_6_HH_Latch(S1 := FALSE, R := TRUE);
    TI_6_LL_Latch(S1 := FALSE, R := TRUE);
    TI_7_HH_Latch(S1 := FALSE, R := TRUE);
    TI_7_LL_Latch(S1 := FALSE, R := TRUE);
    TI_8_HH_Latch(S1 := FALSE, R := TRUE);
    TI_8_LL_Latch(S1 := FALSE, R := TRUE);
    FirstScan    := FALSE;
    RETURN;
END_IF;

FI_1_Scaled := ((INT_TO_REAL(FI_1_Raw) - 6554.0) / (32767.0 - 6554.0)) * 200.0;
FI_2_Scaled := ((INT_TO_REAL(FI_2_Raw) - 6554.0) / (32767.0 - 6554.0)) * 200.0;
FI_3_Scaled := ((INT_TO_REAL(FI_3_Raw) - 6554.0) / (32767.0 - 6554.0)) * 200.0;
TI_1_Scaled := ((INT_TO_REAL(TI_1_Raw) - 6554.0) / (32767.0 - 6554.0)) * 150.0;
TI_4_Scaled := ((INT_TO_REAL(TI_4_Raw) - 6554.0) / (32767.0 - 6554.0)) * 150.0;
TI_5_Scaled := ((INT_TO_REAL(TI_5_Raw) - 6554.0) / (32767.0 - 6554.0)) * 150.0;
TI_6_Scaled := ((INT_TO_REAL(TI_6_Raw) - 6554.0) / (32767.0 - 6554.0)) * 150.0;
TI_7_Scaled := ((INT_TO_REAL(TI_7_Raw) - 6554.0) / (32767.0 - 6554.0)) * 150.0;
TI_8_Scaled := ((INT_TO_REAL(TI_8_Raw) - 6554.0) / (32767.0 - 6554.0)) * 150.0;

FI_1_HH_Latch(
    S1 := FI_1_Scaled >= FI_1_HH_SP,
    R  := FI_1_HH_Ack AND (FI_1_Scaled <= (FI_1_HH_SP - FI_1_Deadband)));
FI_1_LL_Latch(
    S1 := FI_1_Scaled <= FI_1_LL_SP,
    R  := FI_1_LL_Ack AND (FI_1_Scaled >= (FI_1_LL_SP + FI_1_Deadband)));
IF FI_1_Scaled >= FI_1_H_SP THEN
    FI_1_H := TRUE;
ELSIF FI_1_Scaled <= (FI_1_H_SP - FI_1_Deadband) THEN
    FI_1_H := FALSE;
END_IF;
IF FI_1_Scaled <= FI_1_L_SP THEN
    FI_1_L := TRUE;
ELSIF FI_1_Scaled >= (FI_1_L_SP + FI_1_Deadband) THEN
    FI_1_L := FALSE;
END_IF;

FI_2_HH_Latch(
    S1 := FI_2_Scaled >= FI_2_HH_SP,
    R  := FI_2_HH_Ack AND (FI_2_Scaled <= (FI_2_HH_SP - FI_2_Deadband)));
FI_2_LL_Latch(
    S1 := FI_2_Scaled <= FI_2_LL_SP,
    R  := FI_2_LL_Ack AND (FI_2_Scaled >= (FI_2_LL_SP + FI_2_Deadband)));
IF FI_2_Scaled >= FI_2_H_SP THEN
    FI_2_H := TRUE;
ELSIF FI_2_Scaled <= (FI_2_H_SP - FI_2_Deadband) THEN
    FI_2_H := FALSE;
END_IF;
IF FI_2_Scaled <= FI_2_L_SP THEN
    FI_2_L := TRUE;
ELSIF FI_2_Scaled >= (FI_2_L_SP + FI_2_Deadband) THEN
    FI_2_L := FALSE;
END_IF;

FI_3_HH_Latch(
    S1 := FI_3_Scaled >= FI_3_HH_SP,
    R  := FI_3_HH_Ack AND (FI_3_Scaled <= (FI_3_HH_SP - FI_3_Deadband)));
FI_3_LL_Latch(
    S1 := FI_3_Scaled <= FI_3_LL_SP,
    R  := FI_3_LL_Ack AND (FI_3_Scaled >= (FI_3_LL_SP + FI_3_Deadband)));
IF FI_3_Scaled >= FI_3_H_SP THEN
    FI_3_H := TRUE;
ELSIF FI_3_Scaled <= (FI_3_H_SP - FI_3_Deadband) THEN
    FI_3_H := FALSE;
END_IF;
IF FI_3_Scaled <= FI_3_L_SP THEN
    FI_3_L := TRUE;
ELSIF FI_3_Scaled >= (FI_3_L_SP + FI_3_Deadband) THEN
    FI_3_L := FALSE;
END_IF;

TI_1_HH_Latch(
    S1 := TI_1_Scaled >= TI_1_HH_SP,
    R  := TI_1_HH_Ack AND (TI_1_Scaled <= (TI_1_HH_SP - TI_1_Deadband)));
TI_1_LL_Latch(
    S1 := TI_1_Scaled <= TI_1_LL_SP,
    R  := TI_1_LL_Ack AND (TI_1_Scaled >= (TI_1_LL_SP + TI_1_Deadband)));
IF TI_1_Scaled >= TI_1_H_SP THEN
    TI_1_H := TRUE;
ELSIF TI_1_Scaled <= (TI_1_H_SP - TI_1_Deadband) THEN
    TI_1_H := FALSE;
END_IF;
IF TI_1_Scaled <= TI_1_L_SP THEN
    TI_1_L := TRUE;
ELSIF TI_1_Scaled >= (TI_1_L_SP + TI_1_Deadband) THEN
    TI_1_L := FALSE;
END_IF;

TI_4_HH_Latch(
    S1 := TI_4_Scaled >= TI_4_HH_SP,
    R  := TI_4_HH_Ack AND (TI_4_Scaled <= (TI_4_HH_SP - TI_4_Deadband)));
TI_4_LL_Latch(
    S1 := TI_4_Scaled <= TI_4_LL_SP,
    R  := TI_4_LL_Ack AND (TI_4_Scaled >= (TI_4_LL_SP + TI_4_Deadband)));
IF TI_4_Scaled >= TI_4_H_SP THEN
    TI_4_H := TRUE;
ELSIF TI_4_Scaled <= (TI_4_H_SP - TI_4_Deadband) THEN
    TI_4_H := FALSE;
END_IF;
IF TI_4_Scaled <= TI_4_L_SP THEN
    TI_4_L := TRUE;
ELSIF TI_4_Scaled >= (TI_4_L_SP + TI_4_Deadband) THEN
    TI_4_L := FALSE;
END_IF;

TI_5_HH_Latch(
    S1 := TI_5_Scaled >= TI_5_HH_SP,
    R  := TI_5_HH_Ack AND (TI_5_Scaled <= (TI_5_HH_SP - TI_5_Deadband)));
TI_5_LL_Latch(
    S1 := TI_5_Scaled <= TI_5_LL_SP,
    R  := TI_5_LL_Ack AND (TI_5_Scaled >= (TI_5_LL_SP + TI_5_Deadband)));
IF TI_5_Scaled >= TI_5_H_SP THEN
    TI_5_H := TRUE;
ELSIF TI_5_Scaled <= (TI_5_H_SP - TI_5_Deadband) THEN
    TI_5_H := FALSE;
END_IF;
IF TI_5_Scaled <= TI_5_L_SP THEN
    TI_5_L := TRUE;
ELSIF TI_5_Scaled >= (TI_5_L_SP + TI_5_Deadband) THEN
    TI_5_L := FALSE;
END_IF;

TI_6_HH_Latch(
    S1 := TI_6_Scaled >= TI_6_HH_SP,
    R  := TI_6_HH_Ack AND (TI_6_Scaled <= (TI_6_HH_SP - TI_6_Deadband)));
TI_6_LL_Latch(
    S1 := TI_6_Scaled <= TI_6_LL_SP,
    R  := TI_6_LL_Ack AND (TI_6_Scaled >= (TI_6_LL_SP + TI_6_Deadband)));
IF TI_6_Scaled >= TI_6_H_SP THEN
    TI_6_H := TRUE;
ELSIF TI_6_Scaled <= (TI_6_H_SP - TI_6_Deadband) THEN
    TI_6_H := FALSE;
END_IF;
IF TI_6_Scaled <= TI_6_L_SP THEN
    TI_6_L := TRUE;
ELSIF TI_6_Scaled >= (TI_6_L_SP + TI_6_Deadband) THEN
    TI_6_L := FALSE;
END_IF;

TI_7_HH_Latch(
    S1 := TI_7_Scaled >= TI_7_HH_SP,
    R  := TI_7_HH_Ack AND (TI_7_Scaled <= (TI_7_HH_SP - TI_7_Deadband)));
TI_7_LL_Latch(
    S1 := TI_7_Scaled <= TI_7_LL_SP,
    R  := TI_7_LL_Ack AND (TI_7_Scaled >= (TI_7_LL_SP + TI_7_Deadband)));
IF TI_7_Scaled >= TI_7_H_SP THEN
    TI_7_H := TRUE;
ELSIF TI_7_Scaled <= (TI_7_H_SP - TI_7_Deadband) THEN
    TI_7_H := FALSE;
END_IF;
IF TI_7_Scaled <= TI_7_L_SP THEN
    TI_7_L := TRUE;
ELSIF TI_7_Scaled >= (TI_7_L_SP + TI_7_Deadband) THEN
    TI_7_L := FALSE;
END_IF;

TI_8_HH_Latch(
    S1 := TI_8_Scaled >= TI_8_HH_SP,
    R  := TI_8_HH_Ack AND (TI_8_Scaled <= (TI_8_HH_SP - TI_8_Deadband)));
TI_8_LL_Latch(
    S1 := TI_8_Scaled <= TI_8_LL_SP,
    R  := TI_8_LL_Ack AND (TI_8_Scaled >= (TI_8_LL_SP + TI_8_Deadband)));
IF TI_8_Scaled >= TI_8_H_SP THEN
    TI_8_H := TRUE;
ELSIF TI_8_Scaled <= (TI_8_H_SP - TI_8_Deadband) THEN
    TI_8_H := FALSE;
END_IF;
IF TI_8_Scaled <= TI_8_L_SP THEN
    TI_8_L := TRUE;
ELSIF TI_8_Scaled >= (TI_8_L_SP + TI_8_Deadband) THEN
    TI_8_L := FALSE;
END_IF;

FC4_Error    := FC4_SP - FI_1_Scaled;
FC4_Integral := FC4_Integral + (FC4_Ki * FC4_Error);
IF FC4_Integral > 100.0 THEN
    FC4_Integral := 100.0;
ELSIF FC4_Integral < 0.0 THEN
    FC4_Integral := 0.0;
END_IF;
FC4_Output := (FC4_Kp * FC4_Error) + FC4_Integral;
IF FC4_Output > 100.0 THEN
    FC4_Output := 100.0;
ELSIF FC4_Output < 0.0 THEN
    FC4_Output := 0.0;
END_IF;
V_3_Out := REAL_TO_INT(6554.0 + (FC4_Output / 100.0) * (32767.0 - 6554.0));

FC5_Error    := FC5_SP - FI_2_Scaled;
FC5_Integral := FC5_Integral + (FC5_Ki * FC5_Error);
IF FC5_Integral > 100.0 THEN
    FC5_Integral := 100.0;
ELSIF FC5_Integral < 0.0 THEN
    FC5_Integral := 0.0;
END_IF;
FC5_Output := (FC5_Kp * FC5_Error) + FC5_Integral;
IF FC5_Output > 100.0 THEN
    FC5_Output := 100.0;
ELSIF FC5_Output < 0.0 THEN
    FC5_Output := 0.0;
END_IF;
V_4_Out := REAL_TO_INT(6554.0 + (FC5_Output / 100.0) * (32767.0 - 6554.0));

FC6_Error    := FC6_SP - FI_3_Scaled;
FC6_Integral := FC6_Integral + (FC6_Ki * FC6_Error);
IF FC6_Integral > 100.0 THEN
    FC6_Integral := 100.0;
ELSIF FC6_Integral < 0.0 THEN
    FC6_Integral := 0.0;
END_IF;
FC6_Output := (FC6_Kp * FC6_Error) + FC6_Integral;
IF FC6_Output > 100.0 THEN
    FC6_Output := 100.0;
ELSIF FC6_Output < 0.0 THEN
    FC6_Output := 0.0;
END_IF;
V_5_Out := REAL_TO_INT(6554.0 + (FC6_Output / 100.0) * (32767.0 - 6554.0));

TC1_Error    := TC1_SP - TI_1_Scaled;
TC1_Integral := TC1_Integral + (TC1_Ki * TC1_Error);
IF TC1_Integral > 100.0 THEN
    TC1_Integral := 100.0;
ELSIF TC1_Integral < 0.0 THEN
    TC1_Integral := 0.0;
END_IF;
TC1_Output := (TC1_Kp * TC1_Error) + TC1_Integral;
IF TC1_Output > 100.0 THEN
    TC1_Output := 100.0;
ELSIF TC1_Output < 0.0 THEN
    TC1_Output := 0.0;
END_IF;
V_7_Out := REAL_TO_INT(6554.0 + (TC1_Output / 100.0) * (32767.0 - 6554.0));

System_Alarm :=
    FI_1_HH_Latch.Q1 OR FI_1_LL_Latch.Q1 OR FI_1_H OR FI_1_L OR
    FI_2_HH_Latch.Q1 OR FI_2_LL_Latch.Q1 OR FI_2_H OR FI_2_L OR
    FI_3_HH_Latch.Q1 OR FI_3_LL_Latch.Q1 OR FI_3_H OR FI_3_L OR
    TI_1_HH_Latch.Q1 OR TI_1_LL_Latch.Q1 OR TI_1_H OR TI_1_L OR
    TI_4_HH_Latch.Q1 OR TI_4_LL_Latch.Q1 OR TI_4_H OR TI_4_L OR
    TI_5_HH_Latch.Q1 OR TI_5_LL_Latch.Q1 OR TI_5_H OR TI_5_L OR
    TI_6_HH_Latch.Q1 OR TI_6_LL_Latch.Q1 OR TI_6_H OR TI_6_L OR
    TI_7_HH_Latch.Q1 OR TI_7_LL_Latch.Q1 OR TI_7_H OR TI_7_L OR
    TI_8_HH_Latch.Q1 OR TI_8_LL_Latch.Q1 OR TI_8_H OR TI_8_L;
